import { Currency, CurrencyAmount, Price, Token } from '@uniswap/sdk-core'
import { useMemo } from 'react'
import { useQuery } from '@tanstack/react-query'
import { PollingInterval } from 'uniswap/src/constants/misc'
import { USDC_ABSTRACT_MAINNET, USDC_ABSTRACT_TESTNET, getToken } from 'uniswap/src/constants/tokens'
import { UniverseChainId, isUniverseChainId } from 'uniswap/src/features/chains/types'
import { areCurrencyIdsEqual, currencyId } from 'uniswap/src/utils/currencyId'
import { useEnabledChains } from 'uniswap/src/features/chains/hooks/useEnabledChains'

const USDC_DEFAULT_MIN = 1_000e6
const USDC_18_DEFAULT_MIN = 1_000e18

// Stablecoin amounts used when calculating spot price for a given currency.
// Kept for compatibility with callers that use this constant.
export const STABLECOIN_AMOUNT_OUT: Record<UniverseChainId, CurrencyAmount<Token>> = {
  [UniverseChainId.Mainnet]: CurrencyAmount.fromRawAmount(USDC_ABSTRACT_MAINNET, USDC_DEFAULT_MIN),
  [UniverseChainId.Sepolia]: CurrencyAmount.fromRawAmount(USDC_ABSTRACT_TESTNET, USDC_18_DEFAULT_MIN),
}

// Hardcoded USD prices for testnet tokens
const TESTNET_PRICES: Record<string, string> = {
  '0x9edcde0257f2386ce177c3a7fcdd97787f0d841d': '3500', // WETH testnet
  '0xb6313be1c20dc222199ec567951abc6b5b64dfd6': '0.20', // ABX testnet
}

interface DexScreenerToken {
  address: string
  name: string
  symbol: string
}

interface DexScreenerPair {
  chainId: string
  dexId: string
  url: string
  pairAddress: string
  baseToken: DexScreenerToken
  quoteToken: DexScreenerToken
  priceUsd?: string
  liquidity?: {
    usd?: number
  }
}

// DexScreener tokens endpoint returns array directly
type DexScreenerResponse = DexScreenerPair[]

/**
 * Returns the price in USDC of the input currency
 * @param currency currency to compute the USDC price of
 */
export function useUSDCPrice(
  currency?: Currency,
  pollInterval: PollingInterval = PollingInterval.Fast,
): {
  price: Price<Currency, Currency> | undefined
  isLoading: boolean
} {
  const chainId = currency?.chainId
  const { isTestnetModeEnabled } = useEnabledChains()

  // Only allow fetching on the chain that matches the current mode.
  // - Testnet mode: Sepolia only
  // - Mainnet mode: Abstract Mainnet only
  const chainMatchesMode = useMemo(() => {
    if (!isUniverseChainId(chainId)) return false
    return isTestnetModeEnabled ? chainId === UniverseChainId.Sepolia : chainId === UniverseChainId.Mainnet
  }, [chainId, isTestnetModeEnabled])

  const usdcToken = chainMatchesMode && isUniverseChainId(chainId) ? getToken(chainId).usdc : undefined

  // avoid fetching price for stablecoin itself
  const currencyIsStablecoin = Boolean(
    usdcToken && currency && areCurrencyIdsEqual(currencyId(currency), currencyId(usdcToken)),
  )

  // Price fetch: DexScreener for mainnet, hardcoded for testnet
  const { data, isLoading } = useQuery({
    queryKey: ['token-usd-price', chainId, currency?.wrapped.address],
    enabled: Boolean(
      currency &&
      usdcToken &&
      !currencyIsStablecoin &&
      isUniverseChainId(chainId) &&
      chainMatchesMode,
    ),
    refetchInterval: 60000, // Refetch every 60 seconds
    staleTime: 60000, // Cache for 60 seconds
    refetchOnWindowFocus: false,
    queryFn: async (): Promise<Price<Currency, Currency> | null> => {
      if (!currency || !usdcToken || !isUniverseChainId(chainId) || !chainMatchesMode) {
        return null
      }

      const tokenAddr = currency.isNative ? currency.wrapped.address : currency.address
      if (!tokenAddr || tokenAddr.toLowerCase() === '0x0000000000000000000000000000000000000000') {
        return null
      }

      // For testnet, use hardcoded prices
      if (chainId === UniverseChainId.Sepolia) {
        const hardcodedPrice = TESTNET_PRICES[tokenAddr.toLowerCase()]
        if (hardcodedPrice) {
          // Create a Price object: 1 token = X USDC
          // Price(baseCurrency, quoteCurrency, denominator, numerator)
          // denominator = 10^tokenDecimals (represents 1 whole token)
          // numerator = priceUsd * 10^usdcDecimals (represents price in USDC)
          const tokenDecimals = currency.decimals
          const usdcDecimals = usdcToken.decimals
          const denominator = Math.pow(10, tokenDecimals).toString()
          const numerator = (parseFloat(hardcodedPrice) * Math.pow(10, usdcDecimals)).toFixed(0)
          return new Price(currency, usdcToken, denominator, numerator)
        }
        return null
      }

      // For mainnet, use DexScreener API
      try {
        const response = await fetch(
          `https://api.dexscreener.com/tokens/v1/abstract/${tokenAddr}`,
          { headers: { 'Accept': 'application/json' } }
        )

        if (!response.ok) {
          return null
        }

        const pairs: DexScreenerResponse = await response.json()

        if (!pairs || pairs.length === 0) {
          return null
        }

        // Find the pair with highest liquidity that has a USD price
        const bestPair = pairs
          .filter(p => p.priceUsd && p.liquidity?.usd)
          .sort((a, b) => (b.liquidity?.usd || 0) - (a.liquidity?.usd || 0))[0]

        if (!bestPair || !bestPair.priceUsd) {
          return null
        }

        // Create Price object: 1 token = X USDC
        // denominator = 10^tokenDecimals (represents 1 whole token)
        // numerator = priceUsd * 10^usdcDecimals (represents price in USDC)
        const tokenDecimals = currency.decimals
        const usdcDecimals = usdcToken.decimals
        const denominator = Math.pow(10, tokenDecimals).toString()
        const numerator = (parseFloat(bestPair.priceUsd) * Math.pow(10, usdcDecimals)).toFixed(0)
        return new Price(currency, usdcToken, denominator, numerator)
      } catch (error) {
        return null
      }
    },
  })

  return useMemo(() => {
    if (!usdcToken || !chainMatchesMode) {
      return { price: undefined, isLoading: false }
    }

    if (currencyIsStablecoin) {
      return { price: new Price(usdcToken, usdcToken, '1', '1'), isLoading: false }
    }

    return { price: data ?? undefined, isLoading }
  }, [currencyIsStablecoin, data, isLoading, usdcToken])
}

export function useUSDCValue(
  currencyAmount: CurrencyAmount<Currency> | undefined | null,
): CurrencyAmount<Currency> | null {
  const { price } = useUSDCPrice(currencyAmount?.currency)

  return useMemo(() => {
    if (!price || !currencyAmount) {
      return null
    }
    try {
      return price.quote(currencyAmount)
    } catch (error) {
      return null
    }
  }, [currencyAmount, price])
}

/**
 * @param currencyAmount
 * @returns Returns fiat value of the currency amount, and loading status of the currency<->stable quote
 */
export function useUSDCValueWithStatus(currencyAmount: CurrencyAmount<Currency> | undefined | null): {
  value: CurrencyAmount<Currency> | null
  isLoading: boolean
} {
  const { price, isLoading } = useUSDCPrice(currencyAmount?.currency)

  return useMemo(() => {
    if (!price || !currencyAmount) {
      return { value: null, isLoading }
    }
    try {
      return { value: price.quote(currencyAmount), isLoading }
    } catch (error) {
      return {
        value: null,
        isLoading: false,
      }
    }
  }, [currencyAmount, isLoading, price])
}
