"use strict";
import { BigNumber } from "@ethersproject/bignumber";
import { Interface } from "@ethersproject/abi";
import NonfungiblePositionManagerJson from "@uniswap/v3-periphery/artifacts/contracts/NonfungiblePositionManager.sol/NonfungiblePositionManager.json";
import { getAbstractContracts } from "uniswap/src/constants/abstractContracts";
import { contractABIs } from "uniswap/src/constants/cl-contracts";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { getContract } from "utilities/src/contracts/getContract";
const { abi: NON_FUNGIBLE_POSITION_MANAGER_ABI } = NonfungiblePositionManagerJson;
const MAX_UINT128 = BigNumber.from(2).pow(128).sub(1);
const MULTICALL3_ADDRESS = "0xcA11bde05977b3631167028862bE2a173976CA11";
const MULTICALL3_ABI = [
  {
    inputs: [
      {
        components: [
          { name: "target", type: "address" },
          { name: "callData", type: "bytes" }
        ],
        name: "calls",
        type: "tuple[]"
      }
    ],
    name: "aggregate",
    outputs: [
      { name: "blockNumber", type: "uint256" },
      { name: "returnData", type: "bytes[]" }
    ],
    stateMutability: "payable",
    type: "function"
  }
];
function getUniqueAddresses(addresses) {
  const seen = /* @__PURE__ */ new Set();
  const result = [];
  for (const addr of addresses) {
    if (!addr) {
      continue;
    }
    const normalized = addr.toLowerCase();
    if (normalized === "0x0000000000000000000000000000000000000000") {
      continue;
    }
    if (!seen.has(normalized)) {
      seen.add(normalized);
      result.push(addr);
    }
  }
  return result;
}
export async function fetchAbstractV3CollectableFees({
  provider,
  chainId,
  tokenId,
  ownerAddress,
  recipientAddress,
  gaugeAddress
}) {
  if (!provider || !tokenId) {
    return null;
  }
  const contracts = getAbstractContracts(chainId);
  const nftManagerAddress = contracts?.nonfungiblePositionManager;
  if (!nftManagerAddress) {
    console.warn("[ABSTRACT V3 FEES] Missing NonfungiblePositionManager address for chain", chainId);
    return null;
  }
  const recipient = recipientAddress ?? ownerAddress ?? gaugeAddress ?? "0x0000000000000000000000000000000000000000";
  if (recipient === "0x0000000000000000000000000000000000000000") {
    console.warn("[ABSTRACT V3 FEES] Unable to determine recipient for fee simulation", {
      tokenId,
      ownerAddress,
      gaugeAddress
    });
    return null;
  }
  const callers = getUniqueAddresses([ownerAddress ?? void 0, gaugeAddress ?? void 0, recipient]);
  if (callers.length === 0) {
    console.warn("[ABSTRACT V3 FEES] No valid caller available for fee simulation", {
      tokenId,
      ownerAddress,
      gaugeAddress,
      recipient
    });
    return null;
  }
  const positionManager = getContract(
    nftManagerAddress,
    NON_FUNGIBLE_POSITION_MANAGER_ABI,
    provider
  );
  for (const caller of callers) {
    try {
      const [amount0, amount1] = await positionManager.callStatic.collect(
        {
          tokenId,
          recipient,
          amount0Max: MAX_UINT128,
          amount1Max: MAX_UINT128
        },
        { from: caller }
      );
      return {
        amount0: amount0.toString(),
        amount1: amount1.toString()
      };
    } catch (error) {
      console.warn("[ABSTRACT V3 FEES] Failed to simulate collect call", {
        tokenId,
        caller,
        recipient,
        error
      });
    }
  }
  console.error("[ABSTRACT V3 FEES] Unable to fetch collectable fees on-chain", {
    tokenId,
    ownerAddress,
    gaugeAddress,
    recipient
  });
  return null;
}
function getGaugeAbi(chainId) {
  if (chainId === UniverseChainId.Sepolia || chainId === UniverseChainId.AbstractTestnet) {
    return contractABIs.abstractTestnet.CLGauge;
  }
  return contractABIs.abstractMainnet.CLGauge;
}
export async function fetchAbstractV3FeesBatch({
  provider,
  chainId,
  userAddress,
  requests
}) {
  const tradingFees = /* @__PURE__ */ new Map();
  const gaugeRewards = /* @__PURE__ */ new Map();
  const gaugeInfo = /* @__PURE__ */ new Map();
  if (!provider || requests.length === 0) {
    return { tradingFees, gaugeRewards, gaugeInfo };
  }
  const contracts = getAbstractContracts(chainId);
  const nftManagerAddress = contracts?.nonfungiblePositionManager;
  const unstakedRequests = requests.filter((request) => !request.isStaked);
  const stakedRequests = requests.filter((request) => request.isStaked && request.gaugeAddress);
  if (nftManagerAddress && unstakedRequests.length > 0) {
    const positionManager = getContract(
      nftManagerAddress,
      NON_FUNGIBLE_POSITION_MANAGER_ABI,
      provider
    );
    const encodedCalls = unstakedRequests.map(
      (request) => positionManager.interface.encodeFunctionData("collect", [
        {
          tokenId: request.tokenId,
          recipient: request.recipientAddress ?? request.ownerAddress ?? userAddress,
          amount0Max: MAX_UINT128,
          amount1Max: MAX_UINT128
        }
      ])
    );
    try {
      const results = await positionManager.callStatic.multicall(encodedCalls, {
        from: userAddress
      });
      results.forEach((data, index) => {
        try {
          const [amount0, amount1] = positionManager.interface.decodeFunctionResult("collect", data);
          const tokenId = unstakedRequests[index]?.tokenId;
          if (tokenId) {
            tradingFees.set(tokenId, {
              amount0: amount0.toString(),
              amount1: amount1.toString()
            });
          }
        } catch (decodeError) {
          console.warn("[ABSTRACT V3 FEES] Failed to decode multicall collect result", decodeError);
        }
      });
    } catch (error) {
      console.warn("[ABSTRACT V3 FEES] Multicall collect failed, falling back to sequential calls", error);
      for (const request of unstakedRequests) {
        const feeUpdate = await fetchAbstractV3CollectableFees({
          provider,
          chainId,
          tokenId: request.tokenId,
          ownerAddress: request.ownerAddress,
          recipientAddress: request.recipientAddress ?? userAddress,
          gaugeAddress: request.gaugeAddress
        });
        if (feeUpdate) {
          tradingFees.set(request.tokenId, {
            amount0: feeUpdate.amount0,
            amount1: feeUpdate.amount1
          });
        }
      }
    }
  }
  if (stakedRequests.length > 0) {
    const gaugeAbi = getGaugeAbi(chainId);
    if (gaugeAbi) {
      const multicallContract = getContract(MULTICALL3_ADDRESS, MULTICALL3_ABI, provider);
      const gaugeInterface = new Interface(gaugeAbi);
      if (multicallContract) {
        const earnedCalls = stakedRequests.map((request) => ({
          target: request.gaugeAddress,
          callData: gaugeInterface.encodeFunctionData("earned", [
            request.recipientAddress ?? userAddress,
            BigInt(request.tokenId)
          ])
        }));
        try {
          const [, returnData] = await multicallContract.callStatic.aggregate(earnedCalls);
          returnData.forEach((data, index) => {
            try {
              const [amount] = gaugeInterface.decodeFunctionResult("earned", data);
              const tokenId = stakedRequests[index]?.tokenId;
              if (tokenId) {
                gaugeRewards.set(tokenId, amount.toString());
              }
            } catch (decodeError) {
              console.warn("[ABSTRACT V3 FEES] Failed to decode gauge earned result", decodeError);
            }
          });
          const uniqueGaugeAddresses = Array.from(
            new Set(
              stakedRequests.map((request) => request.gaugeAddress).filter((addr) => !!addr).map((addr) => addr.toLowerCase())
            )
          );
          if (uniqueGaugeAddresses.length > 0) {
            const gaugeMetaCalls = [];
            let gaugeHasPool = false;
            try {
              gaugeInterface.getFunction("pool");
              gaugeHasPool = true;
            } catch {
              gaugeHasPool = false;
            }
            uniqueGaugeAddresses.forEach((addr) => {
              gaugeMetaCalls.push({
                target: addr,
                callData: gaugeInterface.encodeFunctionData("rewardRate", [])
              });
              if (gaugeHasPool) {
                gaugeMetaCalls.push({
                  target: addr,
                  callData: gaugeInterface.encodeFunctionData("pool", [])
                });
              }
            });
            const poolInterface = new Interface([
              "function stakedLiquidity() view returns (uint128)"
            ]);
            let poolAddresses = [];
            if (gaugeMetaCalls.length > 0) {
              try {
                const [, gaugeMetaReturnData] = await multicallContract.callStatic.aggregate(gaugeMetaCalls);
                uniqueGaugeAddresses.forEach((addr, idx) => {
                  const offset = idx * (gaugeHasPool ? 2 : 1);
                  const rewardRateData = gaugeMetaReturnData[offset];
                  try {
                    const rewardRate = gaugeInterface.decodeFunctionResult("rewardRate", rewardRateData)[0];
                    let poolAddress;
                    if (gaugeHasPool) {
                      const poolData = gaugeMetaReturnData[offset + 1];
                      poolAddress = gaugeInterface.decodeFunctionResult("pool", poolData)[0];
                      poolAddresses.push(poolAddress.toLowerCase());
                    }
                    gaugeInfo.set(addr, {
                      rewardRate: rewardRate.toString(),
                      poolAddress
                    });
                  } catch (error) {
                    console.warn("[ABSTRACT V3 FEES] Failed to decode gauge metadata", { gauge: addr, error });
                  }
                });
              } catch (error) {
                console.warn("[ABSTRACT V3 FEES] Gauge metadata multicall failed", error);
              }
              if (poolAddresses.length > 0) {
                poolAddresses = Array.from(new Set(poolAddresses));
                const poolCalls = poolAddresses.map((poolAddr) => ({
                  target: poolAddr,
                  callData: poolInterface.encodeFunctionData("stakedLiquidity", [])
                }));
                try {
                  const [, poolReturnData] = await multicallContract.callStatic.aggregate(poolCalls);
                  poolAddresses.forEach((poolAddr, idx) => {
                    try {
                      const stakedLiquidity = poolInterface.decodeFunctionResult("stakedLiquidity", poolReturnData[idx])[0];
                      gaugeInfo.forEach((info, gaugeAddr) => {
                        if (info.poolAddress?.toLowerCase() === poolAddr) {
                          gaugeInfo.set(gaugeAddr, {
                            ...info,
                            totalStakedLiquidity: stakedLiquidity.toString()
                          });
                        }
                      });
                    } catch (error) {
                      console.warn("[ABSTRACT V3 FEES] Failed to decode staked liquidity", { poolAddr, error });
                    }
                  });
                } catch (error) {
                  console.warn("[ABSTRACT V3 FEES] stakedLiquidity multicall failed", error);
                }
              }
            }
          }
        } catch (error) {
          console.warn("[ABSTRACT V3 FEES] Gauge earned multicall failed", error);
          for (const request of stakedRequests) {
            if (!request.gaugeAddress) {
              continue;
            }
            try {
              const gaugeContract = getContract(request.gaugeAddress, gaugeAbi, provider);
              if (!gaugeContract) {
                continue;
              }
              const amount = await gaugeContract.callStatic.earned(
                request.recipientAddress ?? userAddress,
                BigInt(request.tokenId)
              );
              gaugeRewards.set(request.tokenId, amount.toString());
            } catch (singleError) {
              console.warn("[ABSTRACT V3 FEES] Failed to fetch gauge earned for token", {
                tokenId: request.tokenId,
                gaugeAddress: request.gaugeAddress,
                error: singleError
              });
            }
          }
        }
      }
    } else {
      console.warn("[ABSTRACT V3 FEES] Missing CLGauge ABI for chain", chainId);
    }
  }
  return { tradingFees, gaugeRewards, gaugeInfo };
}
