// Lightweight routing debug logger. Enabled by default in non-production builds,
// or when localStorage[DEBUG_KEY] is set to a truthy value ('1'/'true').

const DEBUG_KEY = 'debug:v3routing'

function isTruthy(val: string | null | undefined) {
  if (!val) return false
  const v = val.toLowerCase()
  return v === '1' || v === 'true' || v === 'yes' || v === 'on'
}

export function isRoutingDebug(): boolean {
  try {
    if (typeof window !== 'undefined' && window?.localStorage) {
      const flag = window.localStorage.getItem(DEBUG_KEY)
      if (flag !== null) return isTruthy(flag)
    }
  } catch {}
  return typeof process !== 'undefined' ? process.env.NODE_ENV !== 'production' : true
}

export function routingLog(message: string, data?: unknown) {
  if (!isRoutingDebug()) return
  if (data === undefined) console.log(`[V3Routing] ${message}`)
  else console.log(`[V3Routing] ${message}`, data)
}

export function routingWarn(message: string, data?: unknown) {
  if (!isRoutingDebug()) return
  if (data === undefined) console.warn(`[V3Routing] ${message}`)
  else console.warn(`[V3Routing] ${message}`, data)
}

export function routingError(message: string, data?: unknown) {
  if (!isRoutingDebug()) return
  if (data === undefined) console.error(`[V3Routing] ${message}`)
  else console.error(`[V3Routing] ${message}`, data)
}

export const V3_ROUTING_DEBUG_KEY = DEBUG_KEY

