import { memo, useCallback, useMemo } from 'react'
import { TokenSelectorList } from 'uniswap/src/components/TokenSelector/TokenSelectorList'
import { useCommonTokensOptionsWithFallback } from 'uniswap/src/components/TokenSelector/hooks/useCommonTokensOptionsWithFallback'
import { useFavoriteTokensOptions } from 'uniswap/src/components/TokenSelector/hooks/useFavoriteTokensOptions'
import { usePortfolioTokenOptions } from 'uniswap/src/components/TokenSelector/hooks/usePortfolioTokenOptions'
import { useRecentlySearchedTokens } from 'uniswap/src/components/TokenSelector/hooks/useRecentlySearchedTokens'
import { useTrendingTokensOptions } from 'uniswap/src/components/TokenSelector/hooks/useTrendingTokensOptions'
import { OnSelectCurrency, TokenSectionsHookProps } from 'uniswap/src/components/TokenSelector/types'
import { isSwapListLoading } from 'uniswap/src/components/TokenSelector/utils'
import { OnchainItemSectionName, type OnchainItemSection } from 'uniswap/src/components/lists/OnchainItemList/types'
import { TokenSelectorOption } from 'uniswap/src/components/lists/items/types'
import { useOnchainItemListSection } from 'uniswap/src/components/lists/utils'
import { GqlResult } from 'uniswap/src/data/types'
import { useBridgingTokensOptions } from 'uniswap/src/features/bridging/hooks/tokens'
import { useEnabledChains } from 'uniswap/src/features/chains/hooks/useEnabledChains'
import { isMobileApp } from 'utilities/src/platform'
import { isTokenWhitelistedForIncentives } from 'uniswap/src/constants/tokens'

// eslint-disable-next-line complexity
function useTokenSectionsForSwapInput({
  activeAccountAddress,
  chainFilter,
  oppositeSelectedToken: output,
  excludeNativeTokens = false,
  whitelistedTokensOnly = false,
}: TokenSectionsHookProps & { excludeNativeTokens?: boolean; whitelistedTokensOnly?: boolean }): GqlResult<OnchainItemSection<TokenSelectorOption>[]> {
  const { defaultChainId, isTestnetModeEnabled } = useEnabledChains()
  const {
    data: portfolioTokenOptions,
    error: portfolioTokenOptionsError,
    refetch: refetchPortfolioTokenOptions,
    loading: portfolioTokenOptionsLoading,
  } = usePortfolioTokenOptions(activeAccountAddress, chainFilter)

  const {
    data: trendingTokenOptions,
    error: trendingTokenOptionsError,
    refetch: refetchTrendingTokenOptions,
    loading: trendingTokenOptionsLoading,
  } = useTrendingTokensOptions(activeAccountAddress, chainFilter)

  const {
    data: favoriteTokenOptions,
    error: favoriteTokenOptionsError,
    refetch: refetchFavoriteTokenOptions,
    loading: favoriteTokenOptionsLoading,
  } = useFavoriteTokensOptions(activeAccountAddress, chainFilter)

  const {
    data: commonTokenOptions,
    error: commonTokenOptionsError,
    refetch: refetchCommonTokenOptions,
    loading: commonTokenOptionsLoading,
  } = useCommonTokensOptionsWithFallback(activeAccountAddress, chainFilter ?? output?.chainId ?? defaultChainId)

  const {
    data: bridgingTokenOptions,
    error: bridgingTokenOptionsError,
    refetch: refetchBridgingTokenOptions,
    loading: bridgingTokenOptionsLoading,
    shouldNest: shouldNestBridgingTokens,
  } = useBridgingTokensOptions({ oppositeSelectedToken: output, walletAddress: activeAccountAddress, chainFilter })

  const recentlySearchedTokenOptions = useRecentlySearchedTokens(chainFilter)
  
  // Helper function to filter out native tokens and non-whitelisted tokens
  const filterTokens = useCallback((options: any[] | undefined) => {
    if (!excludeNativeTokens && !whitelistedTokensOnly || !options) {
      return options
    }
    
    return options.filter((option: any) => {
      if (option?.currencyInfo?.currency) {
        const currency = option.currencyInfo.currency
        
        // Filter out native tokens if excludeNativeTokens is true
        if (excludeNativeTokens && (currency.isNative || currency.symbol === 'ETH')) {
          return false
        }
        
        // Filter out non-whitelisted tokens if whitelistedTokensOnly is true
        if (whitelistedTokensOnly && !isTokenWhitelistedForIncentives(currency)) {
          return false
        }
      }
      return true
    })
  }, [excludeNativeTokens, whitelistedTokensOnly])

  const error =
    (!portfolioTokenOptions && portfolioTokenOptionsError) ||
    (!trendingTokenOptions && trendingTokenOptionsError) ||
    (!favoriteTokenOptions && favoriteTokenOptionsError) ||
    (!commonTokenOptions && commonTokenOptionsError) ||
    (!bridgingTokenOptions && bridgingTokenOptionsError)

  const loading =
    (!portfolioTokenOptions && portfolioTokenOptionsLoading) ||
    (!trendingTokenOptions && trendingTokenOptionsLoading) ||
    (!favoriteTokenOptions && favoriteTokenOptionsLoading) ||
    (!commonTokenOptions && commonTokenOptionsLoading) ||
    (!bridgingTokenOptions && bridgingTokenOptionsLoading)

  const refetchAll = useCallback(() => {
    refetchPortfolioTokenOptions?.()
    refetchTrendingTokenOptions?.()
    refetchFavoriteTokenOptions?.()
    refetchCommonTokenOptions?.()
    refetchBridgingTokenOptions?.()
  }, [
    refetchTrendingTokenOptions,
    refetchPortfolioTokenOptions,
    refetchFavoriteTokenOptions,
    refetchCommonTokenOptions,
    refetchBridgingTokenOptions,
  ])

  // Filter out native tokens and non-whitelisted tokens from common tokens
  const filteredCommonTokenOptions = useMemo(() => {
    return filterTokens(commonTokenOptions)
  }, [commonTokenOptions, filterTokens])
  
  const suggestedSectionOptions = useMemo(() => [filteredCommonTokenOptions ?? []], [filteredCommonTokenOptions])
  const suggestedSection = useOnchainItemListSection({
    sectionKey: OnchainItemSectionName.SuggestedTokens,
    options: suggestedSectionOptions,
  })

  // Filter other token options
  const filteredPortfolioTokenOptions = filterTokens(portfolioTokenOptions)
  const filteredRecentlySearchedTokenOptions = filterTokens(recentlySearchedTokenOptions)
  const filteredFavoriteTokenOptions = filterTokens(favoriteTokenOptions)
  const filteredTrendingTokenOptions = filterTokens(trendingTokenOptions)
  const filteredBridgingTokenOptions = filterTokens(bridgingTokenOptions)
  
  const portfolioSection = useOnchainItemListSection({
    sectionKey: OnchainItemSectionName.YourTokens,
    options: filteredPortfolioTokenOptions,
  })
  const recentSection = useOnchainItemListSection({
    sectionKey: OnchainItemSectionName.RecentSearches,
    options: filteredRecentlySearchedTokenOptions,
  })
  const favoriteSection = useOnchainItemListSection({
    sectionKey: OnchainItemSectionName.FavoriteTokens,
    options: filteredFavoriteTokenOptions,
  })
  const trendingSection = useOnchainItemListSection({
    sectionKey: OnchainItemSectionName.TrendingTokens,
    options: filteredTrendingTokenOptions,
  })
  const bridgingSectionTokenOptions: TokenSelectorOption[] = useMemo(
    () => (shouldNestBridgingTokens ? [filteredBridgingTokenOptions ?? []] : filteredBridgingTokenOptions ?? []),
    [filteredBridgingTokenOptions, shouldNestBridgingTokens],
  )
  const bridgingSection = useOnchainItemListSection({
    sectionKey: OnchainItemSectionName.BridgingTokens,
    options: bridgingSectionTokenOptions,
  })

  const sections = useMemo(() => {
    if (isSwapListLoading({ loading, portfolioSection, trendingSection, isTestnetModeEnabled })) {
      return undefined
    }

    if (isTestnetModeEnabled) {
      return [...(suggestedSection ?? []), ...(portfolioSection ?? [])]
    }

    return [
      ...(suggestedSection ?? []),
      // ...(bridgingSection ?? []), // Disabled: Swap across networks
      ...(portfolioSection ?? []),
      ...(recentSection ?? []),
      // TODO(WEB-3061): Favorited wallets/tokens
      // Extension & interface do not support favoriting but has a default list, so we can't rely on empty array check
      ...(isMobileApp ? favoriteSection ?? [] : []),
      ...(trendingSection ?? []),
    ] satisfies OnchainItemSection<TokenSelectorOption>[]
  }, [
    suggestedSection,
    favoriteSection,
    loading,
    trendingSection,
    portfolioSection,
    recentSection,
    isTestnetModeEnabled,
    // bridgingSection, // Removed from dependencies
  ])

  return useMemo(
    () => ({
      data: sections,
      loading,
      error: error || undefined,
      refetch: refetchAll,
    }),
    [error, loading, refetchAll, sections],
  )
}

function _TokenSelectorSwapInputList({
  onSelectCurrency,
  activeAccountAddress,
  chainFilter,
  isKeyboardOpen,
  oppositeSelectedToken,
  excludeNativeTokens = false,
  whitelistedTokensOnly = false,
}: TokenSectionsHookProps & {
  onSelectCurrency: OnSelectCurrency
  excludeNativeTokens?: boolean
  whitelistedTokensOnly?: boolean
}): JSX.Element {
  const {
    data: sections,
    loading,
    error,
    refetch,
  } = useTokenSectionsForSwapInput({
    activeAccountAddress,
    chainFilter,
    oppositeSelectedToken,
    excludeNativeTokens,
    whitelistedTokensOnly,
  })

  // Filter out native tokens and non-whitelisted tokens if needed
  const filteredSections = useMemo(() => {
    if (!excludeNativeTokens && !whitelistedTokensOnly || !sections) {
      return sections
    }
    
    return sections.map(section => ({
      ...section,
      data: section.data.filter((item: any) => {
        // Check if it's a token option (not an array)
        if (!Array.isArray(item) && item?.currencyInfo?.currency) {
          const currency = item.currencyInfo.currency
          
          // Filter out native tokens (ETH)
          if (excludeNativeTokens && (currency.isNative || currency.symbol === 'ETH')) {
            return false
          }
          
          // Filter out non-whitelisted tokens
          if (whitelistedTokensOnly && !isTokenWhitelistedForIncentives(currency)) {
            return false
          }
        }
        return true
      })
    })).filter(section => section.data.length > 0) // Remove empty sections
  }, [sections, excludeNativeTokens, whitelistedTokensOnly])

  return (
    <TokenSelectorList
      showTokenAddress
      chainFilter={chainFilter}
      hasError={Boolean(error)}
      isKeyboardOpen={isKeyboardOpen}
      loading={loading}
      refetch={refetch}
      sections={filteredSections}
      showTokenWarnings={true}
      onSelectCurrency={onSelectCurrency}
    />
  )
}

export const TokenSelectorSwapInputList = memo(_TokenSelectorSwapInputList)
