"use strict";
import { useQuery } from "@tanstack/react-query";
const CHAIN_ID_TO_SUBGRAPH = {
  2741: "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/v2-mainnet/api",
  11124: "https://subgraph.satsuma-prod.com/b2b9afbe3421/aborean/v2-mainnet/api"
};
export function useUSDPrice(currencyAmount, prefetchCurrency) {
  const currency = currencyAmount?.currency ?? prefetchCurrency;
  const chainId = currency?.chainId;
  const subgraphUrl = chainId ? CHAIN_ID_TO_SUBGRAPH[chainId] : void 0;
  const { data, isLoading } = useQuery({
    queryKey: ["usd-price", currency?.wrapped.address, chainId, currencyAmount?.toExact()],
    queryFn: async () => {
      if (!currency || !currencyAmount || !subgraphUrl) {
        return void 0;
      }
      try {
        const tokenAddress = currency.wrapped.address.toLowerCase();
        const query = `{
          tokens(where: { id: "${tokenAddress}" }) {
            id
            derivedETH
          }
          bundle(id: "1") {
            ethPrice
          }
        }`;
        const response = await fetch(subgraphUrl, {
          method: "POST",
          headers: {
            "Content-Type": "application/json"
          },
          body: JSON.stringify({ query })
        });
        if (!response.ok) {
          return void 0;
        }
        const result = await response.json();
        if (!result.data?.bundle) {
          return void 0;
        }
        const ethPriceUSD = parseFloat(result.data.bundle.ethPrice);
        if (!ethPriceUSD || isNaN(ethPriceUSD)) {
          return void 0;
        }
        if (currency.isNative || tokenAddress === "0x3439153eb7af838ad19d56e1571fbd09333c2809") {
          const amount2 = parseFloat(currencyAmount.toExact());
          return amount2 * ethPriceUSD;
        }
        const tokenData = result.data.tokens[0];
        if (!tokenData) {
          return void 0;
        }
        const derivedETH = parseFloat(tokenData.derivedETH);
        if (isNaN(derivedETH)) {
          return void 0;
        }
        const amount = parseFloat(currencyAmount.toExact());
        const tokenPriceUSD = derivedETH * ethPriceUSD;
        return amount * tokenPriceUSD;
      } catch (error) {
        console.warn("Failed to fetch USD price from subgraph:", error);
        return void 0;
      }
    },
    enabled: !!currency && !!currencyAmount && !!subgraphUrl,
    staleTime: 3e4,
    // 30 seconds
    refetchInterval: 6e4
    // Refetch every minute
  });
  return {
    data,
    isLoading
  };
}
